package com.gamelutagpt;

import android.graphics.Bitmap;
import android.graphics.BitmapFactory;
import android.graphics.Canvas;
import android.graphics.Color;
import android.graphics.ColorFilter;
import android.graphics.Matrix;
import android.graphics.Paint;
import android.graphics.PorterDuff;
import android.graphics.PorterDuffColorFilter;
import android.graphics.Rect;
import android.graphics.RectF;
import android.util.Base64;

/**
 * Movement sprite renderer for the standard player character.
 *
 * The gameplay/hitbox logic remains in GameView. This renderer only selects
 * movement artwork. Attacks, guard, hit reactions and supers deliberately use
 * neutral idle until their dedicated sheets are authored.
 */
final class SpriteFighterRenderer {
    private static final int ATLAS_COLUMNS = 8;
    private static final int CELL_W = 112;
    private static final int CELL_H = 105;
    private static final float DRAW_CELL_H = 235f;

    private static final long IDLE_FRAME_NS = 120_000_000L;
    private static final long WALK_FRAME_NS = 90_000_000L;
    private static final long DASH_FRAME_NS = 60_000_000L;
    private static final long CROUCH_FRAME_NS = 65_000_000L;

    private static final Sequence IDLE = new Sequence(0, 8);
    private static final Sequence WALK_FORWARD = new Sequence(8, 8);
    private static final Sequence WALK_BACKWARD = new Sequence(16, 8);
    private static final Sequence CROUCH = new Sequence(24, 8);
    private static final Sequence JUMP_NEUTRAL = new Sequence(32, 8);
    private static final Sequence JUMP_FORWARD = new Sequence(40, 8);
    private static final Sequence JUMP_BACKWARD = new Sequence(48, 5);
    private static final Sequence DASH_FORWARD = new Sequence(53, 5);
    private static final Sequence BACKDASH = new Sequence(58, 3);

    private static final String ATLAS_0 = "";
    private static final String ATLAS_1 = "";
    private static final String ATLAS_2 = "";

    private final Bitmap atlas;
    private final Rect source = new Rect();
    private final RectF destination = new RectF();
    private final float[] matrixValues = new float[9];

    private boolean hasPreviousSample = false;
    private boolean previousGrounded = true;
    private boolean previousCrouching = false;
    private float previousX = 0f;
    private float previousBaseY = 0f;
    private long previousDrawNs = 0L;
    private int airborneMove = 0;
    private long crouchStartedNs = 0L;
    private long crouchReleasedNs = -1L;

    private final ColorFilter hitFlash =
        new PorterDuffColorFilter(
            Color.argb(150, 255, 255, 255),
            PorterDuff.Mode.SRC_ATOP
        );

    private final ColorFilter blockFlash =
        new PorterDuffColorFilter(
            Color.rgb(205, 240, 255),
            PorterDuff.Mode.MULTIPLY
        );

    SpriteFighterRenderer() {
        atlas = decodeAtlas();
    }

    void draw(
        Canvas canvas,
        Paint paint,
        float x,
        float baseY,
        boolean grounded,
        boolean crouching,
        boolean moving,
        float walkTime,
        String attackType,
        float attackTimer,
        int guardPose,
        boolean superPose,
        boolean damageFlash,
        boolean guardFlash
    ) {
        long now = System.nanoTime();
        int facing = facingFromCanvas(canvas);
        float relativeSpeed = sampleRelativeSpeed(x, now, facing);

        if (!grounded && previousGrounded) {
            airborneMove = directionFromSpeed(relativeSpeed, 45f);
        } else if (!grounded) {
            int liveDirection = directionFromSpeed(relativeSpeed, 85f);
            if (liveDirection != 0) airborneMove = liveDirection;
        } else if (grounded && !previousGrounded) {
            airborneMove = 0;
        }

        if (crouching && !previousCrouching) {
            crouchStartedNs = now;
            crouchReleasedNs = -1L;
        } else if (!crouching && previousCrouching) {
            crouchReleasedNs = now;
        }

        int frame = chooseFrame(
            grounded,
            crouching,
            moving,
            walkTime,
            relativeSpeed,
            baseY,
            attackType,
            attackTimer,
            guardPose,
            superPose,
            now
        );

        previousGrounded = grounded;
        previousCrouching = crouching;
        previousBaseY = baseY;

        setSourceRect(frame);

        float drawH = DRAW_CELL_H;
        float drawW = drawH * CELL_W / (float)CELL_H;

        destination.set(
            x - drawW * 0.5f,
            baseY - drawH,
            x + drawW * 0.5f,
            baseY
        );

        paint.setFilterBitmap(true);
        if (damageFlash) {
            paint.setColorFilter(hitFlash);
        } else if (guardFlash) {
            paint.setColorFilter(blockFlash);
        } else {
            paint.setColorFilter(null);
        }

        canvas.drawBitmap(atlas, source, destination, paint);
        paint.setColorFilter(null);
        paint.setFilterBitmap(false);
    }

    private int chooseFrame(
        boolean grounded,
        boolean crouching,
        boolean moving,
        float walkTime,
        float relativeSpeed,
        float baseY,
        String attackType,
        float attackTimer,
        int guardPose,
        boolean superPose,
        long now
    ) {
        boolean combatPose =
            attackTimer > 0f ||
            (attackType != null && !attackType.isEmpty()) ||
            guardPose != 0 ||
            superPose;

        if (combatPose) return IDLE.start;

        if (!grounded) {
            Sequence jump = JUMP_NEUTRAL;
            if (airborneMove > 0) jump = JUMP_FORWARD;
            if (airborneMove < 0) jump = JUMP_BACKWARD;
            return jumpFrame(jump, baseY);
        }

        if (crouching) {
            long elapsed = Math.max(0L, now - crouchStartedNs);
            int local = (int)(elapsed / CROUCH_FRAME_NS);
            local = Math.min(local, CROUCH.count - 1);
            return CROUCH.start + local;
        }

        if (crouchReleasedNs > 0L) {
            long elapsed = now - crouchReleasedNs;
            int releaseFrames = Math.min(4, CROUCH.count);
            long releaseDuration = releaseFrames * CROUCH_FRAME_NS;
            if (elapsed < releaseDuration) {
                int local = (int)(elapsed / CROUCH_FRAME_NS);
                int sourceLocal = CROUCH.count - 1 - local;
                sourceLocal = Math.max(0, sourceLocal);
                return CROUCH.start + sourceLocal;
            }
            crouchReleasedNs = -1L;
        }

        float absSpeed = Math.abs(relativeSpeed);
        if (absSpeed > 470f) {
            if (relativeSpeed < 0f) {
                return timedFrame(BACKDASH, now, DASH_FRAME_NS);
            }
            return timedFrame(DASH_FORWARD, now, DASH_FRAME_NS);
        }

        if (moving || absSpeed > 28f) {
            if (relativeSpeed < -20f) {
                return phaseOrTimedFrame(WALK_BACKWARD, walkTime, now);
            }
            if (relativeSpeed > 20f) {
                return phaseOrTimedFrame(WALK_FORWARD, walkTime, now);
            }
        }

        return timedFrame(IDLE, now, IDLE_FRAME_NS);
    }

    private int jumpFrame(Sequence sequence, float baseY) {
        float rise = previousBaseY - baseY;
        int phaseDirection = 0;
        if (rise > 0.35f) phaseDirection = -1;
        if (rise < -0.35f) phaseDirection = 1;

        float height = Math.max(0f, 560f - baseY);
        float normalizedHeight = clamp(height / 310f, 0f, 1f);
        float progress;
        if (phaseDirection < 0) {
            progress = normalizedHeight * 0.5f;
        } else if (phaseDirection > 0) {
            progress = 1f - normalizedHeight * 0.5f;
        } else {
            progress = 0.5f;
        }

        int local = Math.round(progress * (sequence.count - 1));
        local = Math.max(0, Math.min(sequence.count - 1, local));
        return sequence.start + local;
    }

    private int phaseOrTimedFrame(Sequence sequence, float walkTime, long now) {
        if (walkTime > 0f) {
            int local = ((int)Math.floor(walkTime)) % sequence.count;
            return sequence.start + local;
        }
        return timedFrame(sequence, now, WALK_FRAME_NS);
    }

    private int timedFrame(Sequence sequence, long now, long durationNs) {
        int local = (int)((now / durationNs) % sequence.count);
        return sequence.start + local;
    }

    private int facingFromCanvas(Canvas canvas) {
        Matrix matrix = canvas.getMatrix();
        matrix.getValues(matrixValues);
        return matrixValues[Matrix.MSCALE_X] < 0f ? -1 : 1;
    }

    private float sampleRelativeSpeed(float x, long now, int facing) {
        if (!hasPreviousSample) {
            hasPreviousSample = true;
            previousX = x;
            previousDrawNs = now;
            return 0f;
        }

        long deltaNs = Math.max(1L, now - previousDrawNs);
        float dt = deltaNs / 1_000_000_000f;
        float speed = ((x - previousX) / dt) * facing;
        previousX = x;
        previousDrawNs = now;

        if (!Float.isFinite(speed)) return 0f;
        return clamp(speed, -2200f, 2200f);
    }

    private int directionFromSpeed(float relativeSpeed, float threshold) {
        if (relativeSpeed > threshold) return 1;
        if (relativeSpeed < -threshold) return -1;
        return 0;
    }

    private void setSourceRect(int frame) {
        int column = frame % ATLAS_COLUMNS;
        int row = frame / ATLAS_COLUMNS;
        int left = column * CELL_W;
        int top = row * CELL_H;
        source.set(left, top, left + CELL_W, top + CELL_H);
    }

    private Bitmap decodeAtlas() {
        try {
            StringBuilder encoded = new StringBuilder(72_000);
            encoded.append(ATLAS_0);
            encoded.append(ATLAS_1);
            encoded.append(ATLAS_2);
            byte[] data = Base64.decode(encoded.toString(), Base64.DEFAULT);
            Bitmap decoded = BitmapFactory.decodeByteArray(data, 0, data.length);
            if (decoded != null) {
                decoded.setDensity(Bitmap.DENSITY_NONE);
                return decoded;
            }
        } catch (Throwable ignored) {
            // Artwork must never crash the game.
        }

        Bitmap fallback = Bitmap.createBitmap(
            CELL_W * ATLAS_COLUMNS,
            CELL_H * 8,
            Bitmap.Config.ARGB_8888
        );
        fallback.eraseColor(Color.TRANSPARENT);
        return fallback;
    }

    private static float clamp(float value, float min, float max) {
        return Math.max(min, Math.min(max, value));
    }

    private static final class Sequence {
        final int start;
        final int count;
        Sequence(int start, int count) {
            this.start = start;
            this.count = count;
        }
    }
}